def format_duration(seconds):
    if seconds == 0:
        return "now"

    time_units = [
        (365 * 24 * 3600, "year", "years"),
        (24 * 3600, "day", "days"),
        (3600, "hour", "hours"),
        (60, "minute", "minutes"),
        (1, "second", "seconds")
    ]

    components = []
    for unit, singular, plural in time_units:
        if seconds >= unit:
            count = seconds // unit
            components.append(f"{count} {plural if count > 1 else singular}")
            seconds %= unit

    if len(components) == 1:
        return components[0]
    elif len(components) == 2:
        return f"{components[0]} and {components[1]}"
    else:
        return ", ".join(components[:-1]) + f" and {components[-1]}"

