    # Sort terms by number of variables and then lexicographically
    sorted_terms = sorted(coefficients.items(), key=lambda x: (len(x[0]), x[0]))

    # Construct the output string
    result = []
    for coeff, monomial in sorted_terms:
        if coeff > 0 and result:
            result.append('+')
        result.append(f'{coeff}{monomial}')

    return ''.join(result)

